/**
 * Next-step chips under the latest answer. Built from what the app knows
 * (the site in context, whether it has a quiz or tour), not generated by the
 * model, so they cost no tokens and can't suggest something that doesn't exist.
 */

type Lang = "vi" | "en";

export type FollowUp =
  | { kind: "more"; label: string; prompt: string; depth: "full" }
  | { kind: "next"; label: string; prompt: string }
  | { kind: "quiz" | "tour"; label: string; href: string };

/** Short on purpose: the agent joins messages of six words or fewer to the previous question. */
export const MORE_PROMPT: Record<Lang, string> = {
  en: "Tell me more",
  vi: "Kể thêm cho mình nghe",
};

const NEXT_PROMPT: Record<Lang, string> = {
  en: "Where should I go next?",
  vi: "Mình nên đi đâu tiếp theo?",
};

const LABEL = {
  en: { more: "Tell me more", quiz: "Take the quiz", tour: "Audio tour", next: "Where next?" },
  vi: { more: "Kể thêm", quiz: "Làm bài ôn tập", tour: "Nghe thuyết minh", next: "Đi đâu tiếp?" },
} as const;

export function followUps(args: {
  lang: Lang;
  site: { slug: string; hasQuiz: boolean; hasTour: boolean } | null;
  /** The answer declined for lack of curated content: there is nothing more to tell. */
  refused: boolean;
  /** The user message this answer replied to. */
  lastQuestion: string;
}): FollowUp[] {
  const { lang, site } = args;
  const l = LABEL[lang];
  const chips: FollowUp[] = [];
  const alreadyDeep = args.lastQuestion.trim() === MORE_PROMPT[lang];
  if (!args.refused && !alreadyDeep) {
    chips.push({ kind: "more", label: l.more, prompt: MORE_PROMPT[lang], depth: "full" });
  }
  if (site?.hasQuiz) chips.push({ kind: "quiz", label: l.quiz, href: `/site/${site.slug}/quiz` });
  if (site?.hasTour) chips.push({ kind: "tour", label: l.tour, href: `/site/${site.slug}/tour` });
  chips.push({ kind: "next", label: l.next, prompt: NEXT_PROMPT[lang] });
  return chips;
}
